  /// The colour to use for [light] in the current theme: [light] itself in
  /// light mode (unchanged), its mirrored-tone partner in dark mode.
  /// Prefer `context.adapt(SoftPalette.x)` in widgets.
  static Color adaptive(Color light, bool isDark) {
    if (!isDark) return light;
    final partner = _darkPartner[light.toARGB32()];
    if (partner != null) return partner;
    // Transparent variants (A<n>): partner of the opaque colour, same opacity.
    final opaque = _darkPartner[light.toARGB32() | 0xFF000000];
    return opaque == null ? light : opaque.withValues(alpha: light.a);
  }
